using System;
using System.Drawing;
using System.IO;
using System.Reflection;
using System.Windows.Forms;
using PaoCaixa;
class UiTests {
 static object Field(MainForm f,string name){return typeof(MainForm).GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(f);}
 static void Snap(Form f,string dir,string name){f.Refresh();Application.DoEvents();System.Threading.Thread.Sleep(40);Application.DoEvents();using(var b=new Bitmap(f.ClientSize.Width,f.ClientSize.Height)){using(var g=Graphics.FromImage(b))g.CopyFromScreen(f.PointToScreen(Point.Empty),Point.Empty,f.ClientSize);b.Save(Path.Combine(dir,name+".png"));}Console.WriteLine("UI "+name);}
 [STAThread] static void Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Directory.CreateDirectory(args[1]);var form=new MainForm(args[0]);int phase=0,index=0,wait=0,ticks=0;bool testing=false;var timer=new Timer{Interval=350};timer.Tick+=(s,e)=>{if(testing)return;testing=true;try{ticks++;if(ticks%10==0)Console.WriteLine("UI tick "+ticks+" busy="+Field(form,"busy")+" phase="+phase+" forms="+Application.OpenForms.Count);if(ticks==250){Snap(form,args[1],"diagnostico");foreach(Form other in Application.OpenForms)Console.WriteLine("Form "+other.Text);Environment.Exit(2);}if((bool)Field(form,"busy")||(bool)Field(form,"startupRunning")||(bool)Field(form,"initializing")||form.IsDisposed)return;if(phase==0){((ThemeSwitch)Field(form,"theme")).SelectedIndex=1;form.Refresh();Snap(form,args[1],"login-escuro");((ThemeSwitch)Field(form,"theme")).SelectedIndex=0;form.Refresh();Snap(form,args[1],"login-claro");var root=(Panel)Field(form,"body");var fields=Find<TextBox>(root);if(fields.Count<2)return;fields[0].Text=Store.OwnerEmail;fields[1].Text="Teste-Pdv-2026";Find<Button>(root).Find(b=>b.Text=="Entrar").PerformClick();phase=1;return;}var nav=(SideNavigation)Field(form,"nav");if(phase==1){if(Field(form,"user")==null||!nav.Visible)return;CheckOrder(form);phase=2;index=0;wait=0;}if(wait++<2)return;wait=0;if(phase==2){if(index==4)CheckDatePopup(form,args[1]);CheckPage(form);Snap(form,args[1],"claro-"+index);if(++index<nav.Pages.Count){nav.SelectedIndex=index;return;}((ThemeSwitch)Field(form,"theme")).SelectedIndex=1;index=0;nav.SelectedIndex=0;phase=3;return;}if(phase==3){if(index==4)CheckDatePopup(form,args[1]);CheckPage(form);Snap(form,args[1],"escuro-"+index);if(++index<nav.Pages.Count){nav.SelectedIndex=index;return;}form.ClientSize=new Size(820,590);nav.SelectedIndex=0;phase=4;return;}if(phase==4){CheckPage(form);Snap(form,args[1],"escuro-menor");form.MinimumSize=Size.Empty;form.ClientSize=new Size(820,551);form.PerformLayout();CheckPage(form);Snap(form,args[1],"escuro-menor-janela");CheckCartSizes(form,args[1]);var logout=(Rectangle)typeof(SideNavigation).GetField("logoutHit",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(nav);if(logout.Bottom>nav.Height)throw new Exception("Sair da conta ficou fora da janela menor.");Console.WriteLine("PASS UI menu inteiro em janela menor");form.ClientSize=new Size(1280,780);((ThemeSwitch)Field(form,"theme")).SelectedIndex=0;phase=5;return;}if(phase==5){phase=6;var dialogTimer=new Timer{Interval=500};dialogTimer.Tick+=(sender,ev)=>{if(phase!=6){dialogTimer.Stop();dialogTimer.Dispose();return;}try{Form dialog=null;foreach(Form other in Application.OpenForms)if(other!=form&&other.Text.StartsWith("Pagamento"))dialog=other;if(dialog==null)return;Snap(dialog,args[1],"pagamento-claro");var inputs=Find<TextBox>(dialog);if(inputs.Count<5||!inputs[0].Visible||inputs[0].Text.Length==0)throw new Exception("Campos do pagamento ocultos.");Console.WriteLine("PASS UI diálogo de pagamento e valores preenchidos visíveis");((Button)dialog.CancelButton).PerformClick();phase=7;dialogTimer.Stop();dialogTimer.Dispose();}catch(Exception ex){Console.WriteLine("FAIL UI diálogo "+ex);Environment.Exit(1);}};dialogTimer.Start();Find<Button>((Panel)Field(form,"body")).Find(b=>b.Text.StartsWith("Receber pagamento")).PerformClick();return;}if(phase==6){Form dialog=null;foreach(Form other in Application.OpenForms)if(other!=form&&other.Text.StartsWith("Pagamento"))dialog=other;if(dialog==null)return;Snap(dialog,args[1],"pagamento-claro");var inputs=Find<TextBox>(dialog);if(inputs.Count<5||!inputs[0].Visible||inputs[0].Text.Length==0)throw new Exception("Campos do pagamento ocultos.");((Button)dialog.CancelButton).PerformClick();phase=7;return;}if(phase==7){timer.Stop();Console.WriteLine("PASS UI todas as páginas, temas, carrinho e diálogo");form.Close();}}catch(Exception ex){Console.WriteLine("FAIL UI "+ex);timer.Stop();Environment.Exit(1);}finally{testing=false;}};form.Shown+=(s,e)=>timer.Start();Application.Run(form);}
 static void CheckOrder(MainForm f){var nav=(SideNavigation)Field(f,"nav");if(nav.Width!=232||nav.Pages.Contains("Estoque"))throw new Exception("Menu lateral original não restaurado.");var search=(TextBox)Field(f,"search");if(search==null)throw new Exception("Frente de caixa não é a tela inicial.");var draft=(Draft)Field(f,"draft");long before=0;var products=(System.Collections.Generic.List<Product>)Field(f,"products");var product=products.Find(x=>x.code=="002");var line=draft.cart.Find(x=>x.productId==product.id);if(line!=null)before=line.quantity;search.Text=product.code;var catalog=(ProductCatalog)Field(f,"catalogue");catalog.Refresh();typeof(ProductCatalog).GetMethod("OnMouseClick",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(catalog,new object[]{new MouseEventArgs(MouseButtons.Left,1,40,145,0)});draft=(Draft)Field(f,"draft");if(draft.cart.Find(x=>x.productId==product.id).quantity!=before+1000)throw new Exception("Clique no cartão não adicionou o produto.");var cart=(CartList)Field(f,"cartView");cart.Refresh();int index=draft.cart.FindIndex(x=>x.productId==product.id);typeof(CartList).GetMethod("OnMouseClick",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(cart,new object[]{new MouseEventArgs(MouseButtons.Left,1,158,index*102+77,0)});if(draft.cart.Find(x=>x.productId==product.id).quantity!=before+2000)throw new Exception("Botão + do carrinho não funcionou.");typeof(CartList).GetMethod("OnMouseClick",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(cart,new object[]{new MouseEventArgs(MouseButtons.Left,1,75,index*102+77,0)});if(draft.cart.Find(x=>x.productId==product.id).quantity!=before+1000)throw new Exception("Botão - do carrinho não funcionou.");((ThemeSwitch)Field(f,"theme")).SelectedIndex=1;((ThemeSwitch)Field(f,"theme")).SelectedIndex=0;if(((Draft)Field(f,"draft")).cart.Find(x=>x.productId==product.id).quantity!=before+1000)throw new Exception("Tema alterou os itens.");var note=(TextBox)Field(f,"note");if(note.Text!="Pedido preservado"||!note.Visible)throw new Exception("Observação anterior não exibida.");foreach(Control c in note.Parent.Controls)if(c is Label&&c.Visible)throw new Exception("Placeholder cobriu o valor existente.");var theme=(ThemeSwitch)Field(f,"theme");typeof(ThemeSwitch).GetMethod("OnMouseClick",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(theme,new object[]{new MouseEventArgs(MouseButtons.Left,1,theme.Width-12,18,0)});if(theme.SelectedIndex!=1)throw new Exception("Tema escuro não selecionado ao clicar.");typeof(ThemeSwitch).GetMethod("OnKeyDown",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(theme,new object[]{new KeyEventArgs(Keys.Left)});if(theme.SelectedIndex!=0)throw new Exception("Tema claro não selecionado pelo teclado.");var discount=(TextBox)Field(f,"discount");string oldDiscount=discount.Text;discount.Text="inválido";if(((Button)Field(f,"receive")).Enabled)throw new Exception("Pagamento ficou habilitado com desconto inválido.");discount.Text=oldDiscount;if(!((Button)Field(f,"receive")).Enabled)throw new Exception("Pagamento não reabilitou após corrigir desconto.");Console.WriteLine("PASS UI desconto inválido impede pagamento e correção reabilita");CheckPage(f);CheckWheel(catalog);Console.WriteLine("PASS UI cartão, +, -, tema por clique/teclado preserva pedido, campos visíveis e rolagem suave");}
 static void CheckCartSizes(MainForm f,string dir){var d=(Draft)Field(f,"draft");var saved=d.cart;var initial=saved[0].quantity;var compactCart=(CartList)Field(f,"cartView");compactCart.Refresh();var click=typeof(CartList).GetMethod("OnMouseClick",BindingFlags.NonPublic|BindingFlags.Instance);click.Invoke(compactCart,new object[]{new MouseEventArgs(MouseButtons.Left,1,110,38,0)});if(d.cart[0].quantity!=initial+1000)throw new Exception("+ compacto não alterou quantidade.");click.Invoke(compactCart,new object[]{new MouseEventArgs(MouseButtons.Left,1,23,38,0)});if(d.cart[0].quantity!=initial)throw new Exception("- compacto não restaurou quantidade.");var refresh=typeof(MainForm).GetMethod("RefreshCart",BindingFlags.NonPublic|BindingFlags.Instance);try{d.cart=new System.Collections.Generic.List<Line>();refresh.Invoke(f,null);f.Refresh();CheckPage(f);Snap(f,dir,"venda-vazia-menor");var products=(System.Collections.Generic.List<Product>)Field(f,"products");foreach(var product in products)if(product.active&&product.stock>0)d.cart.Add(new Line{productId=product.id,quantity=product.unit=="kg"?50:1000});refresh.Invoke(f,null);f.Refresh();CheckPage(f);Snap(f,dir,"venda-muitos-itens-menor");var cart=(CartList)Field(f,"cartView");cart.ScrollOffset=new Point(0,100000);f.Refresh();CheckPage(f);if(cart.ScrollBar.Value==0)throw new Exception("Últimos itens não são acessíveis.");}finally{d.cart=saved;refresh.Invoke(f,null);}Console.WriteLine("PASS UI venda vazia e pedido grande com resumo e pagamento fixos");}
 static void CheckDatePopup(MainForm form,string dir){var date=Find<DateField>((Panel)Field(form,"body"))[0];DateTime before=date.Value;date.OpenCalendar();Application.DoEvents();var popup=(ToolStripDropDown)typeof(DateField).GetField("popup",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(date);if(popup==null||!popup.Visible)throw new Exception("Calendário não abriu.");Snap(form,dir,"calendario-claro");var month=(CalendarPicker)((ToolStripControlHost)popup.Items[0]).Control;using(var bitmap=new Bitmap(popup.Width,popup.Height)){using(var graphics=Graphics.FromImage(bitmap))graphics.CopyFromScreen(popup.Location,Point.Empty,popup.Size);bitmap.Save(Path.Combine(dir,Ui.Dark?"seletor-data-escuro.png":"seletor-data-claro.png"));}var expected=new DateTime(2026,10,11);month.SelectedDate=expected;typeof(CalendarPicker).GetMethod("OnKeyDown",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(month,new object[]{new KeyEventArgs(Keys.Enter)});Application.DoEvents();if(date.Value!=expected||!popup.IsDisposed)throw new Exception("Seleção do calendário não atualizou a data.");date.Value=before;Console.WriteLine("PASS UI calendário abre, seleciona data e fecha");}
 static void CheckPage(MainForm f){var body=(Panel)Field(f,"body");var nav=(SideNavigation)Field(f,"nav");if(nav.SelectedPage=="Pedidos"){var cart=(CartList)Field(f,"cartView");var outer=cart.Parent.Parent as Panel;if(outer.AutoScroll||outer.VerticalScroll.Visible||outer.HorizontalScroll.Visible)throw new Exception("Frente de caixa com rolagem externa.");foreach(string name in new[]{"receive","total","discount","note"}){var c=(Control)Field(f,name);var p=body.PointToClient(c.PointToScreen(Point.Empty));if(p.Y<0||p.Y+c.Height>body.Height-body.Padding.Bottom)throw new Exception("Controle da venda cortado: "+name+" "+p.Y+"/"+c.Height+"/"+body.Height);}if(((Draft)Field(f,"draft")).cart.Count==1&&cart.ScrollBar.Visible)throw new Exception("Um único item precisa rolar na janela menor.");if(cart.Parent.Bottom>outer.ClientSize.Height||cart.Height<1)throw new Exception("Painel da venda não cabe.");var total=(Label)Field(f,"total");if(TextRenderer.MeasureText(total.Text,total.Font).Width>total.Width)throw new Exception("Total da venda truncado.");var search=(TextBox)Field(f,"search");if(search.Parent.Top<0)throw new Exception("Busca cortada.");}
  foreach(var date in Find<DateField>(body)){DateTime old=date.Value;date.Value=new DateTime(2026,10,11);if(date.Value!=new DateTime(2026,10,11))throw new Exception("Data não foi mantida.");var text=Find<TextBox>(date)[0];text.Text="31/02/2026";bool denied=false;try{var invalid=date.Value;}catch(Exception){denied=true;}if(!denied)throw new Exception("Data inválida aceita.");date.Value=old;}
  foreach(var pager in Find<PaginationBar>(body)){if(pager.Previous.Right>=pager.Next.Left)throw new Exception("Botões de página sobrepostos.");if(((SoftButton)pager.Previous).IconName!="arrow-left"||((SoftButton)pager.Next).IconName!="arrow"||!((SoftButton)pager.Next).IconRight)throw new Exception("Setas da página ausentes.");}}
 static void CheckWheel(ProductCatalog catalog){catalog.Bind(catalog.Items,catalog.Draft);int before=catalog.ScrollBar.Value;typeof(CanvasView).GetMethod("OnMouseWheel",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(catalog,new object[]{new HandledMouseEventArgs(MouseButtons.None,0,50,50,-120)});if(catalog.ScrollBar.Value!=before)throw new Exception("Rolagem pulou antes da animação.");var watch=System.Diagnostics.Stopwatch.StartNew();while(watch.ElapsedMilliseconds<220){Application.DoEvents();System.Threading.Thread.Sleep(5);}if(SystemInformation.MouseWheelScrollLines!=0&&catalog.ScrollBar.Visible&&catalog.ScrollBar.Value<=before)throw new Exception("Rolagem não avançou.");catalog.ScrollOffset=Point.Empty;}
 static System.Collections.Generic.List<T> Find<T>(Control c)where T:Control {var r=new System.Collections.Generic.List<T>();foreach(Control x in c.Controls){if(x is T)r.Add((T)x);r.AddRange(Find<T>(x));}return r;}
}
